<template><div class="space-y-3 p-4"><div class="flex items-center justify-between"><h1 class="text-xl font-bold text-slate-800">AI solution projects</h1><button class="rounded-xl bg-indigo-500 px-3 py-2 text-xs font-semibold text-white" @click="createProject">New</button></div><NuxtLink v-for="item in items" :key="item.id" :to="`/buyer/projects/${item.id}`" class="m-card block"><div class="flex justify-between gap-3"><p class="text-sm font-semibold text-slate-800">{{ item.title }}</p><span class="status-pill bg-indigo-50 text-indigo-600">{{ item.status }}</span></div><p class="mt-2 text-xs text-slate-400">{{ item.project_type }}</p></NuxtLink><p v-if="!items.length&&!error" class="m-card text-sm text-slate-500">No projects yet.</p><p v-if="error" class="m-card text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const {apiFetch}=useApi();const items=ref<any[]>([]);const error=ref('');async function load(){items.value=(await apiFetch<any>('/buyer/projects')).items}async function createProject(){const title=window.prompt('Project title');if(!title)return;const row=await apiFetch<any>('/buyer/projects',{method:'POST',body:{title}});await navigateTo(`/buyer/projects/${row.id}`)}onMounted(()=>load().catch((e:any)=>error.value=e?.data?.detail||e?.message))</script>
